// Sucht die bestehende Buchung dieses Kunden. Gesucht wird ausschliesslich
// innerhalb des Event-Types aus der Kunden-Config.
const e = $input.first().json;
const p = e.params || {};
const c = e.config || {};

function normTelefon(t) {
  let s = String(t || '').trim().replace(/[^0-9+]/g, '');
  if (s.startsWith('00')) s = '+' + s.slice(2);
  if (s.startsWith('0')) s = '+49' + s.slice(1);
  return s;
}

const referenz = String(p.referenz || p.bestaetigungsnummer || '').trim();
const telefon = normTelefon(p.telefon);
const name = String(p.name || '').trim().toLowerCase();

let fehler = '';
if (!c.cal_event_type_id) fehler = 'kalender nicht konfiguriert';
else if (!referenz && !telefon && !name) fehler = 'kein suchkriterium';

return [{ json: Object.assign({}, e, {
  referenz: referenz, telefon: telefon, name_such: name,
  grund: String(p.grund || 'Absage per Telefonagent').slice(0, 200),
  fehler: fehler,
}) }];

const ktx = $('Eingaben pruefen').first().json;
// Vereinheitlicht die Antwort. Kein Sub-Workflow gibt je etwas anderes
// zurueck als { success, data, message } - darauf bauen die Retell-Agenten
// ihre Erfolgs- und Fehlerzweige auf.
function antwort(success, data, message) {
  return { success: !!success, data: data || {}, message: String(message || '') };
}

if (ktx.fehler) return [{ json: { gefunden: false, message: ktx.fehler } }];

const r = $input.first().json || {};
if (r.error || Number(r.statusCode) >= 400) {
  return [{ json: { gefunden: false, message: 'kalender nicht erreichbar' } }];
}

const liste = ((r.body || {}).data) || [];
const zielTyp = String(ktx.config.cal_event_type_id);

function ziffern(t) { return String(t || '').replace(/[^0-9]/g, '').slice(-9); }

let treffer = null;
if (ktx.referenz) {
  treffer = liste.find(b => String(b.uid) === ktx.referenz || String(b.id) === ktx.referenz) || null;
}
if (!treffer && ktx.telefon) {
  const ziel = ziffern(ktx.telefon);
  treffer = liste.find(b => (b.attendees || []).some(a =>
    ziffern(a.phoneNumber) === ziel || ziffern(a.phone) === ziel)) || null;
}
if (!treffer && ktx.name_such) {
  treffer = liste.find(b => (b.attendees || []).some(a =>
    String(a.name || '').trim().toLowerCase() === ktx.name_such)) || null;
}

if (!treffer) {
  return [{ json: { gefunden: false, message: 'kein passender termin gefunden' } }];
}

// MANDANTENCHECK vor dem schreibenden Schritt: die gefundene Buchung muss zum
// Event-Type dieses Kunden gehoeren. Ohne diesen Check koennte eine
// manipulierte Referenz auf einen fremden Termin zeigen.
const typTreffer = String(treffer.eventTypeId || (treffer.eventType && treffer.eventType.id) || '');
if (typTreffer && typTreffer !== zielTyp) {
  return [{ json: { gefunden: false, message: 'termin gehoert nicht zu diesem betrieb' } }];
}

return [{ json: { gefunden: true, uid: String(treffer.uid || treffer.id),
  start_alt: String(treffer.start || ''), message: '' } }];

const ktx = $('Eingaben pruefen').first().json;
// Vereinheitlicht die Antwort. Kein Sub-Workflow gibt je etwas anderes
// zurueck als { success, data, message } - darauf bauen die Retell-Agenten
// ihre Erfolgs- und Fehlerzweige auf.
function antwort(success, data, message) {
  return { success: !!success, data: data || {}, message: String(message || '') };
}

// Fehlerpfade zuerst: fehlende Eingaben, nicht gefundene oder fremde Buchung.
if (ktx.fehler) return [{ json: antwort(false, {}, ktx.fehler) }];

const item = $input.first().json || {};
if (item.gefunden === false) {
  return [{ json: antwort(false, { storniert: false }, item.message || 'kein termin gefunden') }];
}
if (item.error) return [{ json: antwort(false, { storniert: false }, 'kalender nicht erreichbar') }];
if (Number(item.statusCode) >= 400) {
  return [{ json: antwort(false, { storniert: false, code: Number(item.statusCode) },
    Number(item.statusCode) === 409 ? 'neuer termin nicht frei' : 'aenderung fehlgeschlagen') }];
}

const d = (item.body || {}).data || {};
const gewaehlt = $('Buchung waehlen').first().json;
return [{ json: antwort(true, {
  storniert: true,
  bestaetigungsnummer: String(d.uid || gewaehlt.uid || ''),
  start: String(d.start || ''),
  alter_termin: String(gewaehlt.start_alt || ''),
}, 'termin storniert') }];
